1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	
4	const BASE_PREMIUMS: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: 25,
10	};
11	
12	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
13	// floating-point error that shifts the spec's round-up in MHPCO's favour.
14	const percentOf = (percent: number, amount: number): number => (amount * percent) / 100;
15	
16	export type ScenarioResult = { premium: number };
17	
18	type Item = { type: string };
19	
20	type Scenario = {
21	  steps: { items: Item[] }[];
22	};
23	
24	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
25	
26	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
27	  const [quoteStep] = scenario.steps;
28	  const policyBasePremium = quoteStep.items.reduce(
29	    (total, item) => total + basePremiumForItem(item),
30	    0,
31	  );
32	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
33	  const premium = Math.ceil(policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE);
34	  return { results: [{ premium }] };
35	};
